import { Heart, Star, ThumbsUp } from 'lucide-react';
import { useState } from 'react';

import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { getNumber } from '@/components/formedible/fields/advanced-field-utils';
import { Button } from '@/components/ui/button';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';
import { cn } from '@/lib/utils';

const icons = { star: Star, heart: Heart, thumbs: ThumbsUp } as const;
const sizes = { sm: 'size-4', md: 'size-6', lg: 'size-8' } as const;
const halfStepEpsilon = 1e-6;

function isRatingChecked(value: number, rating: number): boolean {
  return Math.abs(value - rating) < halfStepEpsilon;
}

export function RatingField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const config = fieldConfig.ratingConfig;
  const max = config?.max ?? 5;
  const icon = config?.icon ?? 'star';
  const Icon = icons[icon];
  const value = getNumber(field.value, 0);
  const [hoverValue, setHoverValue] = useState<number | undefined>();
  const activeValue = hoverValue ?? value;

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <div className="space-y-2">
        {config?.showValue && <div className="text-xs text-muted-foreground">({value}/{max})</div>}
        <div className="flex items-center gap-1" role="radiogroup" aria-label={typeof fieldConfig.label === 'string' ? fieldConfig.label : field.name}>
          {Array.from({ length: max }, (_, index) => {
            const rating = index + 1;
            const halfRating = index + 0.5;
            const isFull = activeValue >= rating;
            const isHalf = !isFull && config?.allowHalf === true && activeValue >= halfRating;
            const iconSize = sizes[config?.size ?? 'md'];

            return (
              <span key={rating} className="relative inline-flex">
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  role="radio"
                  aria-checked={isRatingChecked(value, rating)}
                  aria-label={`Rate ${rating}`}
                  disabled={fieldConfig.disabled}
                  className="transition-transform hover:scale-110 disabled:cursor-not-allowed disabled:opacity-50"
                  onBlur={field.onBlur}
                  onClick={() => field.onChange(rating)}
                  onMouseEnter={() => setHoverValue(rating)}
                  onMouseLeave={() => setHoverValue(undefined)}
                >
                  {isFull ? (
                    <Icon className={cn(iconSize, activeClass(icon))} />
                  ) : isHalf ? (
                    <span className="relative inline-flex" data-slot="rating-half">
                      <Icon className={cn(iconSize, 'text-muted-foreground')} />
                      <span aria-hidden="true" className="absolute inset-y-0 left-0 w-1/2 overflow-hidden">
                        <Icon className={cn(iconSize, activeClass(icon))} />
                      </span>
                    </span>
                  ) : (
                    <Icon className={cn(iconSize, 'text-muted-foreground')} />
                  )}
                </Button>
                {config?.allowHalf && (
                  <Button
                    type="button"
                    variant="ghost"
                    role="radio"
                    aria-checked={isRatingChecked(value, halfRating)}
                    aria-label={`Rate ${halfRating}`}
                    disabled={fieldConfig.disabled}
                    className="absolute inset-y-0 left-0 h-auto w-1/2 p-0 disabled:cursor-not-allowed"
                    onClick={() => field.onChange(halfRating)}
                    onMouseEnter={() => setHoverValue(halfRating)}
                    onMouseLeave={() => setHoverValue(undefined)}
                  />
                )}
              </span>
            );
          })}
          {value > 0 && (
            <Button type="button" variant="ghost" disabled={fieldConfig.disabled} className="ml-2 h-auto text-xs text-muted-foreground hover:text-foreground" onClick={() => field.onChange(0)}>
              Clear
            </Button>
          )}
        </div>
      </div>
    </FieldWrapper>
  );
}

function activeClass(icon: 'star' | 'heart' | 'thumbs'): string {
  if (icon === 'heart') {
    return 'fill-red-500 text-red-500';
  }

  if (icon === 'thumbs') {
    return 'fill-blue-500 text-blue-500';
  }

  return 'fill-yellow-400 text-yellow-400';
}

import { Check, ChevronDown, X } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';

import { getStringArray, labelToText, resolveFieldOptions } from '@/components/formedible/fields/advanced-field-utils';
import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';
import { cn } from '@/lib/utils';

export function MultiSelectField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const config = fieldConfig.multiSelectConfig;
  const selectedValues = getStringArray(field.value);
  const options = resolveFieldOptions(fieldConfig, field.formValues);
  const [isOpen, setIsOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const containerRef = useRef<HTMLDivElement>(null);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const maxSelections = config?.maxSelections ?? Number.POSITIVE_INFINITY;
  const searchable = config?.searchable ?? true;
  const filteredOptions = options.filter((option) => `${option.value} ${labelToText(option.label)}`.toLowerCase().includes(searchQuery.toLowerCase()));
  const canCreate = config?.creatable === true && searchQuery.trim() !== '' && !options.some((option) => option.value.toLowerCase() === searchQuery.trim().toLowerCase());
  const displayOptions = canCreate ? [{ value: searchQuery.trim(), label: `Create "${searchQuery.trim()}"` }, ...filteredOptions] : filteredOptions;

  useEffect(() => {
    function handlePointerDown(event: MouseEvent) {
      const target = event.target;

      if (target instanceof Node && !containerRef.current?.contains(target)) {
        setIsOpen(false);
        setSearchQuery('');
      }
    }

    document.addEventListener('mousedown', handlePointerDown);
    return () => document.removeEventListener('mousedown', handlePointerDown);
  }, []);

  useEffect(() => {
    if (isOpen && searchable) {
      window.requestAnimationFrame(() => searchInputRef.current?.focus());
    }
  }, [isOpen, searchable]);

  function toggleValue(value: string) {
    if (selectedValues.includes(value)) {
      field.onChange(selectedValues.filter((selectedValue) => selectedValue !== value));
    } else if (selectedValues.length < maxSelections) {
      field.onChange([...selectedValues, value]);
    }

    setSearchQuery('');
    if (searchable) {
      window.requestAnimationFrame(() => searchInputRef.current?.focus());
    } else {
      setIsOpen(false);
    }
  }

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <div ref={containerRef} className="relative space-y-2">
        {maxSelections < Number.POSITIVE_INFINITY && <div className="text-sm text-muted-foreground">({selectedValues.length}/{maxSelections})</div>}
        <Button
          type="button"
          variant="outline"
          disabled={fieldConfig.disabled}
          aria-expanded={isOpen}
          aria-invalid={field.error ? true : undefined}
          className={cn('min-h-9 w-full justify-start bg-transparent px-3 py-2 text-left text-sm shadow-xs disabled:cursor-not-allowed disabled:opacity-50', fieldConfig.inputClassName)}
          onClick={() => setIsOpen((open) => !open)}
          onBlur={field.onBlur}
        >
          <span className="flex flex-wrap items-center gap-1">
            {selectedValues.length === 0 && <span className="text-muted-foreground">{config?.placeholder ?? fieldConfig.placeholder ?? 'Select options...'}</span>}
            {selectedValues.map((value) => {
              const option = options.find((item) => item.value === value);
              const label = option?.label ?? value;
              const removeLabel = labelToText(label) || value;
              return (
                <Badge key={value} variant="secondary" className="gap-1">
                  {label}
                  <span
                    role="button"
                    tabIndex={fieldConfig.disabled ? -1 : 0}
                    aria-label={`Remove ${removeLabel}`}
                    className="inline-flex size-4 shrink-0 cursor-pointer items-center justify-center rounded-sm text-muted-foreground transition-colors hover:bg-destructive/10 hover:text-destructive focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                    onClick={(event) => {
                      event.stopPropagation();
                      if (!fieldConfig.disabled) {
                        toggleValue(value);
                      }
                    }}
                    onKeyDown={(event) => {
                      if (event.key !== 'Enter' && event.key !== ' ') {
                        return;
                      }

                      event.preventDefault();
                      event.stopPropagation();
                      if (!fieldConfig.disabled) {
                        toggleValue(value);
                      }
                    }}
                  >
                    <X className="size-3" />
                  </span>
                </Badge>
              );
            })}
            <ChevronDown className="ml-auto size-4 opacity-50" />
          </span>
        </Button>
        {isOpen && (
          <div className="absolute z-50 w-full rounded-md border bg-popover p-1 text-popover-foreground shadow-md">
            {searchable && <Input ref={searchInputRef} value={searchQuery} placeholder={fieldConfig.placeholder ?? 'Search options...'} className="mb-1" onChange={(event) => setSearchQuery(event.target.value)} />}
            <div className="max-h-60 overflow-y-auto">
              {displayOptions.length === 0 && <div className="p-2 text-center text-sm text-muted-foreground">{config?.noOptionsText ?? 'No options found'}</div>}
              {displayOptions.map((option) => {
                const isSelected = selectedValues.includes(option.value);
                const isDisabled = !isSelected && selectedValues.length >= maxSelections;

                return (
                  <Button
                    key={option.value}
                    type="button"
                    variant="ghost"
                    disabled={isDisabled || fieldConfig.disabled || option.disabled}
                    className="flex h-auto w-full justify-between rounded-sm px-2 py-1.5 text-left text-sm"
                    onClick={() => toggleValue(option.value)}
                  >
                    <span>{option.label}</span>
                    {isSelected && <Check className="size-4" />}
                  </Button>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </FieldWrapper>
  );
}

import { Check, ChevronsUpDown } from 'lucide-react';
import { useEffect, useState } from 'react';

import { labelToText, resolveFieldOptions } from '@/components/formedible/fields/advanced-field-utils';
import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { Button } from '@/components/ui/button';
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from '@/components/ui/command';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';
import { cn } from '@/lib/utils';

export function ComboboxField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const config = fieldConfig.comboboxConfig;
  const value = typeof field.value === 'string' ? field.value : '';
  const options = resolveFieldOptions(fieldConfig, field.formValues);
  const selectedOption = options.find((option) => option.value === value);
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState('');
  const searchable = config?.searchable ?? true;
  const displayOptions = searchable ? options.filter((option) => `${option.value} ${labelToText(option.label)}`.toLowerCase().includes(query.toLowerCase())) : options;

  useEffect(() => {
    if (!open) {
      setQuery('');
    }
  }, [open]);

  function selectOption(nextValue: string) {
    field.onChange(nextValue === value ? '' : nextValue);
    setOpen(false);
  }

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger
          render={
            <Button
              type="button"
              variant="outline"
              role="combobox"
              aria-expanded={open}
              aria-haspopup="listbox"
              className={cn('w-full justify-between', fieldConfig.inputClassName)}
              disabled={fieldConfig.disabled}
              onBlur={field.onBlur}
            />
          }
        >
          <span className={selectedOption ? undefined : 'text-muted-foreground'}>{selectedOption?.label ?? config?.placeholder ?? fieldConfig.placeholder ?? 'Select an option'}</span>
          <ChevronsUpDown className="size-4 opacity-50" />
        </PopoverTrigger>
        <PopoverContent className="w-full p-0" align="start">
          <Command>
            {searchable && <CommandInput value={query} placeholder={config?.searchPlaceholder ?? 'Search options...'} className="h-9" onValueChange={setQuery} />}
            <CommandList>
              {displayOptions.length === 0 && <CommandEmpty>{config?.noOptionsText ?? 'No options found.'}</CommandEmpty>}
              <CommandGroup>
                {displayOptions.map((option) => (
                  <CommandItem key={option.value} value={`${option.value} ${labelToText(option.label)}`} disabled={option.disabled} aria-selected={value === option.value} onSelect={() => selectOption(option.value)}>
                    <Check className={cn('size-4', value === option.value ? 'opacity-100' : 'opacity-0')} />
                    {option.label}
                  </CommandItem>
                ))}
              </CommandGroup>
            </CommandList>
          </Command>
        </PopoverContent>
      </Popover>
    </FieldWrapper>
  );
}

import { useEffect, useMemo, useRef, useState } from 'react';

import { labelToText, normalizeOption, resolveFieldOptions } from '@/components/formedible/fields/advanced-field-utils';
import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import type { FormedibleFieldOption, FormedibleFieldRenderProps, FormedibleFormValues, FormedibleOptionConfig } from '@/lib/formedible/types';
import { cn } from '@/lib/utils';

function normalizeAutocompleteOptions(options: readonly FormedibleFieldOption[] | undefined): readonly FormedibleOptionConfig[] {
  return options?.map(normalizeOption) ?? [];
}

interface RenderedAutocompleteOptionsInput {
  readonly configOptions?: readonly FormedibleFieldOption[];
  readonly fallbackOptions: readonly FormedibleFieldOption[];
  readonly query: string;
  readonly minChars: number;
  readonly maxResults: number;
}

interface AutocompleteSelection {
  readonly inputValue: string;
  readonly fieldValue: string;
}

export function shouldCommitCustomAutocompleteValue(allowCustom: boolean | undefined): boolean {
  return allowCustom ?? true;
}

export function getNextAutocompleteRequestId(currentRequestId: number): number {
  return currentRequestId + 1;
}

export function isCurrentAutocompleteRequest(requestId: number, currentRequestId: number): boolean {
  return requestId === currentRequestId;
}

export function getRenderedAutocompleteOptions({
  configOptions,
  fallbackOptions,
  query,
  minChars,
  maxResults,
}: RenderedAutocompleteOptionsInput): readonly FormedibleOptionConfig[] {
  const compatibilityOptions = normalizeAutocompleteOptions(configOptions);
  const staticOptions = configOptions !== undefined ? compatibilityOptions : normalizeAutocompleteOptions(fallbackOptions);
  const normalizedQuery = query.toLowerCase();

  if (normalizedQuery.length < minChars) {
    return [];
  }

  return staticOptions
    .filter((option) => `${option.value} ${labelToText(option.label)}`.toLowerCase().includes(normalizedQuery))
    .slice(0, maxResults);
}

export function getAutocompleteSelection(option: FormedibleOptionConfig): AutocompleteSelection {
  return {
    inputValue: labelToText(option.label) || option.value,
    fieldValue: option.value,
  };
}

export function getAutocompleteDisplayText(value: unknown, options: readonly FormedibleOptionConfig[]): string {
  if (typeof value !== 'string') {
    return '';
  }

  const matchedOption = options.find((option) => option.value === value);

  return matchedOption ? labelToText(matchedOption.label) || matchedOption.value : value;
}

export function AutocompleteField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const config = fieldConfig.autocompleteConfig;
  const debounceMs = config?.debounceMs ?? 300;
  const minChars = config?.minChars ?? 1;
  const maxResults = config?.maxResults ?? 10;
  const allowCustom = config?.allowCustom ?? true;
  const noOptionsText = config?.noOptionsText ?? 'No options found';
  const loadingText = config?.loadingText ?? 'Loading...';
  const [inputValue, setInputValue] = useState(typeof field.value === 'string' ? field.value : '');
  const [isOpen, setIsOpen] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [asyncOptions, setAsyncOptions] = useState<readonly FormedibleOptionConfig[]>([]);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const asyncRequestIdRef = useRef(0);
  const lastSyncedValueRef = useRef<unknown>(field.value);

  const staticOptions = useMemo(() => {
    const compatibilityOptions = normalizeAutocompleteOptions(config?.options);

    return config?.options !== undefined ? compatibilityOptions : resolveFieldOptions(fieldConfig, field.formValues);
  }, [config?.options, field.formValues, fieldConfig]);

  const selectionOptions = config?.asyncOptions ? asyncOptions : staticOptions;

  useEffect(() => {
    if (field.value === lastSyncedValueRef.current) {
      return;
    }

    lastSyncedValueRef.current = field.value;
    setInputValue(getAutocompleteDisplayText(field.value, selectionOptions));
  }, [field.value, selectionOptions]);

  const filteredOptions = useMemo(() => {
    const query = inputValue.toLowerCase();

    if (config?.asyncOptions) {
      return asyncOptions;
    }

    if (query.length < minChars) {
      return [];
    }

    return staticOptions
      .filter((option) => `${option.value} ${labelToText(option.label)}`.toLowerCase().includes(query))
      .slice(0, maxResults);
  }, [asyncOptions, config?.asyncOptions, inputValue, maxResults, minChars, staticOptions]);

  useEffect(() => {
    if (!config?.asyncOptions) {
      return undefined;
    }

    if (debounceRef.current) {
      clearTimeout(debounceRef.current);
    }

    if (inputValue.length < minChars) {
      asyncRequestIdRef.current = getNextAutocompleteRequestId(asyncRequestIdRef.current);
      setAsyncOptions([]);
      setIsLoading(false);
      return undefined;
    }

    const loadOptions = config.asyncOptions;
    const requestId = getNextAutocompleteRequestId(asyncRequestIdRef.current);
    asyncRequestIdRef.current = requestId;

    debounceRef.current = setTimeout(() => {
      setIsLoading(true);
      loadOptions(inputValue)
        .then((options) => {
          if (isCurrentAutocompleteRequest(requestId, asyncRequestIdRef.current)) {
            setAsyncOptions(normalizeAutocompleteOptions(options).slice(0, maxResults));
          }
        })
        .catch((error: unknown) => {
          if (isCurrentAutocompleteRequest(requestId, asyncRequestIdRef.current)) {
            console.error('Autocomplete async options error:', error);
            setAsyncOptions([]);
          }
        })
        .finally(() => {
          if (isCurrentAutocompleteRequest(requestId, asyncRequestIdRef.current)) {
            setIsLoading(false);
          }
        });
    }, debounceMs);

    return () => {
      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
      }
      if (isCurrentAutocompleteRequest(requestId, asyncRequestIdRef.current)) {
        asyncRequestIdRef.current = getNextAutocompleteRequestId(asyncRequestIdRef.current);
      }
    };
  }, [config, debounceMs, inputValue, maxResults, minChars]);

  const showDropdown = isOpen && (isLoading || inputValue.length >= minChars);

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <div className="relative">
        <Input
          id={field.id}
          name={field.name}
          type="text"
          value={inputValue}
          placeholder={fieldConfig.placeholder ?? config?.placeholder ?? 'Type to search...'}
          autoComplete="off"
          disabled={fieldConfig.disabled}
          required={fieldConfig.required}
          aria-invalid={field.error ? true : undefined}
          className={cn(fieldConfig.inputClassName, isOpen && 'rounded-b-none')}
          onBlur={() => {
            field.onBlur();
            if (shouldCommitCustomAutocompleteValue(allowCustom)) {
              field.onChange(inputValue);
              lastSyncedValueRef.current = inputValue;
            } else {
              setInputValue(getAutocompleteDisplayText(field.value, selectionOptions));
              lastSyncedValueRef.current = field.value;
            }
            setTimeout(() => setIsOpen(false), 150);
          }}
          onChange={(event) => {
            const value = event.target.value;
            setInputValue(value);
            setIsOpen(true);
          }}
          onFocus={() => {
            if (inputValue.length >= minChars) {
              setIsOpen(true);
            }
          }}
        />
        {showDropdown && (
          <div className="absolute left-0 right-0 top-full z-50 max-h-60 overflow-y-auto rounded-b-md border border-t-0 bg-popover p-1 text-popover-foreground shadow-md">
            {isLoading && <div className="px-3 py-2 text-sm text-muted-foreground">{loadingText}</div>}
            {!isLoading && filteredOptions.length === 0 && <div className="px-3 py-2 text-sm text-muted-foreground">{noOptionsText}</div>}
            {!isLoading &&
              filteredOptions.map((option) => (
                <Button
                  key={option.value}
                  type="button"
                  variant="ghost"
                  disabled={option.disabled || fieldConfig.disabled}
                  className="flex h-auto w-full flex-col items-start rounded-sm px-3 py-2 text-left text-sm"
                  onMouseDown={(event) => event.preventDefault()}
                  onClick={() => {
                    const selection = getAutocompleteSelection(option);
                    setInputValue(selection.inputValue);
                    field.onChange(selection.fieldValue);
                    lastSyncedValueRef.current = selection.fieldValue;
                    setIsOpen(false);
                  }}
                >
                  <span className="font-medium">{option.label}</span>
                  {option.value !== labelToText(option.label) && <span className="text-xs text-muted-foreground">{option.value}</span>}
                </Button>
              ))}
          </div>
        )}
      </div>
    </FieldWrapper>
  );
}

import { MultiSelectField } from '@/components/formedible/fields/multi-select-field';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';

export function MultiComboboxField<TFormValues extends FormedibleFormValues>(props: FormedibleFieldRenderProps<TFormValues>) {
  return <MultiSelectField {...props} fieldConfig={{ ...props.fieldConfig, multiSelectConfig: props.fieldConfig.multiComboboxConfig ?? props.fieldConfig.multiSelectConfig }} />;
}

import { Check, Palette } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';

import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';
import { cn } from '@/lib/utils';

const defaultPresets = ['#ff0000', '#ff8000', '#ffff00', '#00ff00', '#00ffff', '#0000ff', '#8000ff', '#ff00ff', '#000000', '#808080', '#ffffff'] as const;

export function ColorPickerField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const config = fieldConfig.colorConfig;
  const format = config?.format ?? 'hex';
  const storedValue = typeof field.value === 'string' ? field.value : '';
  const hexValue = normalizeHex(storedValue);
  const presets = config?.presetColors ?? defaultPresets;
  const allowCustom = config?.allowCustom ?? true;
  const [draft, setDraft] = useState<string | null>(null);
  const committedValueRef = useRef<unknown>(field.value);
  const draftIsInvalid = draft !== null && draft.trim() !== '' && parseColorText(draft) === undefined;

  useEffect(() => {
    if (field.value !== committedValueRef.current) {
      committedValueRef.current = field.value;
      setDraft(null);
    }
  }, [field.value]);

  function commitHex(nextHex: string) {
    const nextValue = formatColor(nextHex, format);
    committedValueRef.current = nextValue;
    field.onChange(nextValue);
  }

  function commitColor(color: string) {
    setDraft(null);
    commitHex(normalizeHex(color));
  }

  function commitDraft() {
    if (draft === null) {
      return;
    }

    const draftHex = parseColorText(draft);
    setDraft(null);
    if (draftHex === undefined) {
      return;
    }

    const formatted = formatColor(draftHex, format);
    if (storedValue !== formatted) {
      committedValueRef.current = formatted;
      field.onChange(formatted);
    }
  }

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <div className="space-y-3">
        <div className="flex gap-2">
          <div className="relative">
            <Button variant="outline" className="size-9 p-0" disabled={fieldConfig.disabled} style={{ backgroundColor: hexValue }}>
              {config?.showPreview === false && <Palette className="size-4" />}
            </Button>
            <Input
              data-slot="color-input"
              type="color"
              value={hexValue}
              disabled={fieldConfig.disabled}
              className="absolute inset-0 size-full cursor-pointer opacity-0 disabled:cursor-not-allowed"
              onBlur={field.onBlur}
              onChange={(event) => commitColor(event.target.value)}
            />
          </div>
          {allowCustom && (
            <Input
              value={draft ?? formatColor(hexValue, format)}
              placeholder="#000000"
              disabled={fieldConfig.disabled}
              aria-invalid={field.error || draftIsInvalid ? true : undefined}
              className={fieldConfig.inputClassName}
              onBlur={() => {
                commitDraft();
                field.onBlur();
              }}
              onChange={(event) => {
                const nextDraft = event.target.value;
                setDraft(nextDraft);
                const nextHex = parseColorText(nextDraft);
                if (nextHex !== undefined && nextHex.toLowerCase() !== hexValue.toLowerCase()) {
                  commitHex(nextHex);
                }
              }}
            />
          )}
        </div>
        {allowCustom && draftIsInvalid && (
          <p data-slot="color-invalid-hint" className="text-sm text-destructive">
            Enter a valid color, e.g. #ff0000, rgb(255, 0, 0), or hsl(0, 100%, 50%).
          </p>
        )}
        <div className="grid grid-cols-8 gap-2">
          {presets.map((color) => {
            const normalizedPreset = normalizeHex(color);
            return (
              <Button
                key={color}
                type="button"
                variant="ghost"
                size="icon"
                disabled={fieldConfig.disabled}
                className={cn('size-7 rounded border transition-transform hover:scale-110 disabled:cursor-not-allowed disabled:opacity-50', hexValue.toLowerCase() === normalizedPreset.toLowerCase() ? 'ring-2 ring-ring ring-offset-2' : '')}
                style={{ backgroundColor: normalizedPreset }}
                onClick={() => commitColor(normalizedPreset)}
              >
                {hexValue.toLowerCase() === normalizedPreset.toLowerCase() && <Check className="mx-auto size-4 text-white drop-shadow" />}
              </Button>
            );
          })}
        </div>
      </div>
    </FieldWrapper>
  );
}

function parseColorText(value: string): string | undefined {
  const trimmed = value.trim();
  if (/^#[0-9a-fA-F]{6}$/.test(trimmed)) {
    return trimmed;
  }

  if (/^[0-9a-fA-F]{6}$/.test(trimmed)) {
    return `#${trimmed}`;
  }

  const rgb = parseRgbColor(trimmed);
  if (rgb) {
    return rgbToHex(rgb.r, rgb.g, rgb.b);
  }

  const hsl = parseHslColor(trimmed);
  if (hsl) {
    const hslRgb = hslToRgb(hsl.h, hsl.s, hsl.l);
    return rgbToHex(hslRgb.r, hslRgb.g, hslRgb.b);
  }

  return undefined;
}

function normalizeHex(value: string): string {
  return parseColorText(value) ?? '#000000';
}

function parseRgbColor(value: string): { readonly r: number; readonly g: number; readonly b: number } | undefined {
  const match = /^rgb\(\s*(\d{1,3})\s*,\s*(\d{1,3})\s*,\s*(\d{1,3})\s*\)$/i.exec(value);
  if (!match) {
    return undefined;
  }

  const [, rText, gText, bText] = match;
  if (rText === undefined || gText === undefined || bText === undefined) {
    return undefined;
  }

  const r = Number.parseInt(rText, 10);
  const g = Number.parseInt(gText, 10);
  const b = Number.parseInt(bText, 10);

  if (!isValidRgbChannel(r) || !isValidRgbChannel(g) || !isValidRgbChannel(b)) {
    return undefined;
  }

  return { r, g, b };
}

function parseHslColor(value: string): { readonly h: number; readonly s: number; readonly l: number } | undefined {
  const match = /^hsl\(\s*(-?\d+(?:\.\d+)?)\s*,\s*(\d+(?:\.\d+)?)%\s*,\s*(\d+(?:\.\d+)?)%\s*\)$/i.exec(value);
  if (!match) {
    return undefined;
  }

  const [, hText, sText, lText] = match;
  if (hText === undefined || sText === undefined || lText === undefined) {
    return undefined;
  }

  const h = Number.parseFloat(hText);
  const s = Number.parseFloat(sText);
  const l = Number.parseFloat(lText);

  if (!Number.isFinite(h) || !isValidPercentage(s) || !isValidPercentage(l)) {
    return undefined;
  }

  return { h, s, l };
}

function isValidRgbChannel(value: number): boolean {
  return Number.isInteger(value) && value >= 0 && value <= 255;
}

function isValidPercentage(value: number): boolean {
  return Number.isFinite(value) && value >= 0 && value <= 100;
}

function rgbToHex(r: number, g: number, b: number): string {
  return `#${toHexChannel(r)}${toHexChannel(g)}${toHexChannel(b)}`;
}

function toHexChannel(value: number): string {
  return Math.round(value).toString(16).padStart(2, '0');
}

function formatColor(hex: string, format: 'hex' | 'rgb' | 'hsl'): string {
  const rgb = hexToRgb(hex);
  if (format === 'rgb') {
    return `rgb(${rgb.r}, ${rgb.g}, ${rgb.b})`;
  }

  if (format === 'hsl') {
    const hsl = rgbToHsl(rgb.r, rgb.g, rgb.b);
    return `hsl(${hsl.h}, ${hsl.s}%, ${hsl.l}%)`;
  }

  return hex;
}

function hexToRgb(hex: string): { readonly r: number; readonly g: number; readonly b: number } {
  return { r: Number.parseInt(hex.slice(1, 3), 16), g: Number.parseInt(hex.slice(3, 5), 16), b: Number.parseInt(hex.slice(5, 7), 16) };
}

function hslToRgb(h: number, s: number, l: number): { readonly r: number; readonly g: number; readonly b: number } {
  const normalizedHue = (((h % 360) + 360) % 360) / 360;
  const saturation = s / 100;
  const lightness = l / 100;

  if (saturation === 0) {
    const gray = lightness * 255;
    return { r: gray, g: gray, b: gray };
  }

  const q = lightness < 0.5 ? lightness * (1 + saturation) : lightness + saturation - lightness * saturation;
  const p = 2 * lightness - q;

  return {
    r: hueToRgbChannel(p, q, normalizedHue + 1 / 3) * 255,
    g: hueToRgbChannel(p, q, normalizedHue) * 255,
    b: hueToRgbChannel(p, q, normalizedHue - 1 / 3) * 255,
  };
}

function hueToRgbChannel(p: number, q: number, t: number): number {
  let ratio = t;
  if (ratio < 0) {
    ratio += 1;
  }
  if (ratio > 1) {
    ratio -= 1;
  }
  if (ratio < 1 / 6) {
    return p + (q - p) * 6 * ratio;
  }
  if (ratio < 1 / 2) {
    return q;
  }
  if (ratio < 2 / 3) {
    return p + (q - p) * (2 / 3 - ratio) * 6;
  }

  return p;
}

function rgbToHsl(r: number, g: number, b: number): { readonly h: number; readonly s: number; readonly l: number } {
  const rRatio = r / 255;
  const gRatio = g / 255;
  const bRatio = b / 255;
  const max = Math.max(rRatio, gRatio, bRatio);
  const min = Math.min(rRatio, gRatio, bRatio);
  const diff = max - min;
  const lightness = (max + min) / 2;
  const saturation = diff === 0 ? 0 : diff / (1 - Math.abs(2 * lightness - 1));
  let hue = 0;

  if (diff !== 0 && max === rRatio) {
    hue = 60 * (((gRatio - bRatio) / diff) % 6);
  } else if (diff !== 0 && max === gRatio) {
    hue = 60 * ((bRatio - rRatio) / diff + 2);
  } else if (diff !== 0) {
    hue = 60 * ((rRatio - gRatio) / diff + 4);
  }

  return { h: Math.round(hue < 0 ? hue + 360 : hue), s: Math.round(saturation * 100), l: Math.round(lightness * 100) };
}

import { ChevronDown, Phone } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';

import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';
import { cn } from '@/lib/utils';

const countries = {
  US: { code: '+1', name: 'United States', flag: '🇺🇸', format: '(###) ###-####' },
  CA: { code: '+1', name: 'Canada', flag: '🇨🇦', format: '(###) ###-####' },
  GB: { code: '+44', name: 'United Kingdom', flag: '🇬🇧', format: '#### ### ####' },
  FR: { code: '+33', name: 'France', flag: '🇫🇷', format: '## ## ## ## ##' },
  DE: { code: '+49', name: 'Germany', flag: '🇩🇪', format: '### ### ####' },
  IT: { code: '+39', name: 'Italy', flag: '🇮🇹', format: '### ### ####' },
  ES: { code: '+34', name: 'Spain', flag: '🇪🇸', format: '### ### ###' },
  AU: { code: '+61', name: 'Australia', flag: '🇦🇺', format: '#### ### ###' },
  JP: { code: '+81', name: 'Japan', flag: '🇯🇵', format: '##-####-####' },
  CN: { code: '+86', name: 'China', flag: '🇨🇳', format: '### #### ####' },
  IN: { code: '+91', name: 'India', flag: '🇮🇳', format: '##### #####' },
  BR: { code: '+55', name: 'Brazil', flag: '🇧🇷', format: '(##) #####-####' },
  MX: { code: '+52', name: 'Mexico', flag: '🇲🇽', format: '## #### ####' },
  RU: { code: '+7', name: 'Russia', flag: '🇷🇺', format: '### ###-##-##' },
  KR: { code: '+82', name: 'South Korea', flag: '🇰🇷', format: '##-####-####' },
} as const;

type CountryCode = keyof typeof countries;

export function PhoneField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const config = fieldConfig.phoneConfig;
  const defaultCountry = isCountryCode(config?.defaultCountry) ? config.defaultCountry : 'US';
  const [open, setOpen] = useState(false);
  const [selectedCountry, setSelectedCountry] = useState<CountryCode>(() => getAllowedDefaultCountry(defaultCountry, config?.allowedCountries));
  const dropdownContainerRef = useRef<HTMLDivElement | null>(null);
  const value = typeof field.value === 'string' ? field.value : '';
  const country = countries[selectedCountry];
  const phoneNumber = stripCountryCode(value, country.code);
  const availableCountries = countryCodes.filter((code) => config?.allowedCountries === undefined || config.allowedCountries.includes(code));

  useEffect(() => {
    const nextFallback = getAllowedDefaultCountry(defaultCountry, config?.allowedCountries);

    if (!availableCountries.includes(selectedCountry)) {
      setSelectedCountry(nextFallback);
      return;
    }

    const valueCountry = countryCodeFromValue(value, nextFallback, config?.allowedCountries);

    if (valueCountry && value.startsWith(countries[valueCountry].code)) {
      setSelectedCountry(valueCountry);
    }
  }, [availableCountries, config?.allowedCountries, defaultCountry, selectedCountry, value]);

  useEffect(() => {
    if (!open) {
      return undefined;
    }

    function handlePointerDown(event: PointerEvent) {
      const container = dropdownContainerRef.current;

      if (container && container.contains(event.target as Node)) {
        return;
      }

      setOpen(false);
    }

    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === 'Escape') {
        setOpen(false);
      }
    }

    document.addEventListener('pointerdown', handlePointerDown);
    document.addEventListener('keydown', handleKeyDown);

    return () => {
      document.removeEventListener('pointerdown', handlePointerDown);
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [open]);

  function updateValue(countryCode: CountryCode, nextValue: string) {
    if (nextValue.replace(/\D/g, '').length === 0) {
      field.onChange('');
      return;
    }

    const nextCountry = countries[countryCode];
    const formatted = formatPhone(nextValue, nextCountry.format);
    field.onChange(config?.format === 'international' ? `${nextCountry.code} ${formatted}`.trim() : formatted);
  }

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <div className="space-y-2">
        <div className="flex">
          <div className="relative" ref={dropdownContainerRef}>
            <Button variant="outline" className="rounded-r-none border-r-0" disabled={fieldConfig.disabled} onClick={() => setOpen((isOpen) => !isOpen)}>
              {country.code}
              <ChevronDown className="size-3" />
            </Button>
            {open && (
              <div data-slot="phone-country-menu" className="absolute z-50 mt-1 min-w-48 rounded-md border bg-popover p-1 shadow-md">
                {availableCountries.map((code) => (
                  <Button
                    key={code}
                    type="button"
                    variant="ghost"
                    className={cn('h-auto w-full justify-start rounded-sm px-2 py-1.5 text-left text-sm', selectedCountry === code ? 'bg-accent' : '')}
                    onClick={() => {
                      setSelectedCountry(code);
                      updateValue(code, phoneNumber);
                      setOpen(false);
                    }}
                  >
                    <span className="mr-2">{countries[code].flag}</span>
                    {countries[code].name} {countries[code].code}
                  </Button>
                ))}
              </div>
            )}
          </div>
          <Input
            id={field.id}
            name={field.name}
            value={phoneNumber}
            placeholder={config?.placeholder ?? formatPhone('1234567890', country.format)}
            disabled={fieldConfig.disabled}
            aria-invalid={field.error ? true : undefined}
            className={cn('rounded-l-none', fieldConfig.inputClassName)}
            onBlur={field.onBlur}
            onChange={(event) => updateValue(selectedCountry, event.target.value)}
          />
        </div>
        <div className="flex items-center gap-2 text-xs text-muted-foreground">
          <Phone className="size-3" />
          Format: {country.format.replaceAll('#', '0')}
        </div>
      </div>
    </FieldWrapper>
  );
}

const countryCodes = Object.keys(countries).filter(isCountryCode);

function isCountryCode(value: unknown): value is CountryCode {
  return typeof value === 'string' && value in countries;
}

function formatPhone(value: string, format: string): string {
  const digits = value.replace(/\D/g, '');
  let formatted = '';
  let digitIndex = 0;

  for (const character of format) {
    if (character === '#') {
      if (digitIndex >= digits.length) {
        break;
      }
      formatted += digits[digitIndex];
      digitIndex += 1;
    } else {
      formatted += character;
    }
  }

  return formatted;
}

function getAllowedDefaultCountry(fallback: CountryCode, allowedCountries: readonly string[] | undefined): CountryCode {
  return allowedCountries === undefined || allowedCountries.includes(fallback) ? fallback : countryCodes.find((code) => allowedCountries.includes(code)) ?? fallback;
}

function countryCodeFromValue(value: string, fallback: CountryCode, allowedCountries: readonly string[] | undefined): CountryCode | undefined {
  const preferredCodes = [fallback, ...countryCodes.filter((code) => code !== fallback)].filter((code) => allowedCountries === undefined || allowedCountries.includes(code));

  for (const code of preferredCodes) {
    if (value.startsWith(countries[code].code)) {
      return code;
    }
  }

  return undefined;
}

function stripCountryCode(value: string, code: string): string {
  return value.startsWith(code) ? value.slice(code.length).trim() : value;
}

import { useEffect, useRef, useState } from 'react';

import { clamp } from '@/components/formedible/fields/advanced-field-utils';
import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import type { FormedibleDurationConfig, FormedibleDurationValue, FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';

type DurationUnit = 'h' | 'm' | 's';
type DurationFormat = NonNullable<FormedibleDurationConfig['format']>;

interface DurationParts {
  readonly hours: number;
  readonly minutes: number;
  readonly seconds: number;
}

const durationUnitsByFormat: Record<DurationFormat, ReadonlySet<DurationUnit>> = {
  hms: new Set<DurationUnit>(['h', 'm', 's']),
  hm: new Set<DurationUnit>(['h', 'm']),
  ms: new Set<DurationUnit>(['m', 's']),
  hours: new Set<DurationUnit>(['h']),
  minutes: new Set<DurationUnit>(['m']),
  seconds: new Set<DurationUnit>(['s']),
};

const zeroDuration: DurationParts = { hours: 0, minutes: 0, seconds: 0 };

export function DurationPickerField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const config = fieldConfig.durationConfig;
  const format: DurationFormat = config?.format ?? 'hms';
  const units = durationUnitsByFormat[format];
  const maxHours = config?.maxHours ?? 23;
  const maxMinutes = config?.maxMinutes ?? 59;
  const maxSeconds = config?.maxSeconds ?? 59;
  const parts = parseDuration(field.value, format);
  const committedValueRef = useRef<unknown>(field.value);
  const [draft, setDraft] = useState<string | null>(null);

  useEffect(() => {
    if (field.value !== committedValueRef.current) {
      committedValueRef.current = field.value;
      setDraft(null);
    }
  }, [field.value]);

  function commit(nextParts: DurationParts) {
    const nextValue = formatDurationOutput(nextParts, format);
    committedValueRef.current = nextValue;
    field.onChange(nextValue);
  }

  function update(nextParts: DurationParts) {
    setDraft(null);
    commit(nextParts);
  }

  function updatePart(partName: keyof DurationParts, value: number) {
    update({ ...parts, [partName]: value });
  }

  function commitDraft() {
    if (draft === null) {
      return;
    }

    const parsed = parseDurationText(draft, format, maxHours, maxMinutes, maxSeconds);
    setDraft(null);
    if (parsed && !isSameDuration(parsed, parts)) {
      commit(parsed);
    }
  }

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <div className="space-y-3">
        <div className="flex gap-3">
          {units.has('h') && <DurationSelect unit="hours" label="Hours" value={parts.hours} max={maxHours} disabled={fieldConfig.disabled} onChange={(value) => updatePart('hours', value)} />}
          {units.has('m') && <DurationSelect unit="minutes" label="Minutes" value={parts.minutes} max={maxMinutes} disabled={fieldConfig.disabled} onChange={(value) => updatePart('minutes', value)} />}
          {units.has('s') && <DurationSelect unit="seconds" label="Seconds" value={parts.seconds} max={maxSeconds} disabled={fieldConfig.disabled} onChange={(value) => updatePart('seconds', value)} />}
        </div>
        <Input
          value={draft ?? formatDurationText(parts, units)}
          placeholder={fieldConfig.placeholder ?? 'Enter duration (e.g., 1h 30m 45s)'}
          disabled={fieldConfig.disabled}
          className={fieldConfig.inputClassName}
          onBlur={() => {
            commitDraft();
            field.onBlur();
          }}
          onChange={(event) => {
            const nextDraft = event.target.value;
            setDraft(nextDraft);
            const parsed = parseDurationText(nextDraft, format, maxHours, maxMinutes, maxSeconds);
            if (parsed && !isSameDuration(parsed, parts)) {
              commit(parsed);
            }
          }}
        />
        <div className="text-sm text-muted-foreground">Total: {parts.hours * 3600 + parts.minutes * 60 + parts.seconds} seconds</div>
      </div>
    </FieldWrapper>
  );
}

interface DurationSelectProps {
  readonly unit: 'hours' | 'minutes' | 'seconds';
  readonly label: string;
  readonly value: number;
  readonly max: number;
  readonly disabled: boolean;
  readonly onChange: (value: number) => void;
}

function DurationSelect({ unit, label, value, max, disabled, onChange }: DurationSelectProps) {
  return (
    <div className="space-y-1" data-slot="duration-select" data-unit={unit}>
      <div className="text-xs text-muted-foreground">{label}</div>
      <Select value={String(value)} disabled={disabled} onValueChange={(nextValue) => onChange(Number(nextValue ?? 0))}>
        <SelectTrigger className="w-24">
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {Array.from({ length: max + 1 }, (_, index) => (
            <SelectItem key={index} value={String(index)}>
              {String(index).padStart(2, '0')}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </div>
  );
}

function parseDuration(value: unknown, format: DurationFormat): DurationParts {
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) {
      return zeroDuration;
    }

    if (format === 'hours') {
      return parseTotalSeconds(Math.round(value * 3600));
    }

    if (format === 'minutes') {
      return parseTotalSeconds(Math.round(value * 60));
    }

    return parseTotalSeconds(value);
  }

  if (isDurationValue(value)) {
    return { hours: value.hours, minutes: value.minutes, seconds: value.seconds };
  }

  return zeroDuration;
}

function isDurationValue(value: unknown): value is FormedibleDurationValue {
  return typeof value === 'object' && value !== null && 'hours' in value && 'minutes' in value && 'seconds' in value;
}

function parseTotalSeconds(value: number): DurationParts {
  const totalSeconds = Math.abs(value);

  return { hours: Math.floor(totalSeconds / 3600), minutes: Math.floor((totalSeconds % 3600) / 60), seconds: totalSeconds % 60 };
}

function parseDurationText(value: string, format: DurationFormat, maxHours: number, maxMinutes: number, maxSeconds: number): DurationParts | undefined {
  const hours = value.match(/(\d+)h/i);
  const minutes = value.match(/(\d+)m(?!s)/i);
  const seconds = value.match(/(\d+)s/i);

  if (hours !== null || minutes !== null || seconds !== null) {
    return {
      hours: clamp(Number.parseInt(hours?.[1] ?? '0', 10), 0, maxHours),
      minutes: clamp(Number.parseInt(minutes?.[1] ?? '0', 10), 0, maxMinutes),
      seconds: clamp(Number.parseInt(seconds?.[1] ?? '0', 10), 0, maxSeconds),
    };
  }

  const bare = value.trim();
  if (/^\d+$/.test(bare)) {
    const amount = Number.parseInt(bare, 10);

    if (format === 'hours') {
      return { hours: clamp(amount, 0, maxHours), minutes: 0, seconds: 0 };
    }

    if (format === 'minutes') {
      return { hours: 0, minutes: clamp(amount, 0, maxMinutes), seconds: 0 };
    }

    if (format === 'seconds') {
      return { hours: 0, minutes: 0, seconds: clamp(amount, 0, maxSeconds) };
    }
  }

  return undefined;
}

function formatDurationText(parts: DurationParts, units: ReadonlySet<DurationUnit>): string {
  const output: string[] = [];
  if (units.has('h') && parts.hours > 0) {
    output.push(`${parts.hours}h`);
  }
  if (units.has('m') && parts.minutes > 0) {
    output.push(`${parts.minutes}m`);
  }
  if (units.has('s') && parts.seconds > 0) {
    output.push(`${parts.seconds}s`);
  }

  return output.join(' ') || '0';
}

function formatDurationOutput(parts: DurationParts, format: DurationFormat): number | FormedibleDurationValue {
  const totalSeconds = parts.hours * 3600 + parts.minutes * 60 + parts.seconds;

  if (format === 'hours') {
    return parts.hours + parts.minutes / 60 + parts.seconds / 3600;
  }

  if (format === 'minutes') {
    return parts.hours * 60 + parts.minutes + parts.seconds / 60;
  }

  if (format === 'seconds') {
    return totalSeconds;
  }

  return { ...parts, totalSeconds };
}

function isSameDuration(left: DurationParts, right: DurationParts): boolean {
  return left.hours === right.hours && left.minutes === right.minutes && left.seconds === right.seconds;
}

import { MapPin, Navigation, Search, X } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';

import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import type { FormedibleFieldRenderProps, FormedibleFormValues, FormedibleLocationValue } from '@/lib/formedible/types';
import { cn } from '@/lib/utils';

export function LocationPickerField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const config = fieldConfig.locationConfig;
  const value = isLocationValue(field.value) ? field.value : null;
  const draft = isLocationDraftValue(field.value) ? field.value : {};
  const query = value ? value.address ?? `${value.lat}, ${value.lng}` : draft.query ?? '';
  const manualLat = draft.manualLat ?? '';
  const manualLng = draft.manualLng ?? '';
  const [results, setResults] = useState<readonly FormedibleLocationValue[]>([]);
  const [showResults, setShowResults] = useState(false);
  const [error, setError] = useState<string | undefined>();
  const searchContainerRef = useRef<HTMLDivElement | null>(null);
  const enableSearch = config?.enableSearch ?? true;
  const enableGeolocation = config?.enableGeolocation ?? true;
  const enableManualEntry = config?.enableManualEntry ?? true;
  const searchOptions = config?.searchOptions;
  const minQueryLength = searchOptions?.minQueryLength ?? 2;
  const maxResults = searchOptions?.maxResults ?? 5;

  useEffect(() => {
    if (typeof window === 'undefined' || !enableSearch || query.length < minQueryLength || !config?.searchCallback) {
      setResults([]);
      return;
    }

    let isActive = true;
    const timeout = window.setTimeout(() => {
      Promise.resolve(config.searchCallback?.(query, { limit: maxResults }) ?? [])
        .then((nextResults) => {
          if (isActive) {
            setResults(nextResults);
            setShowResults(true);
          }
        })
        .catch(() => {
          if (isActive) {
            setError('Search failed. Please try again.');
          }
        });
    }, searchOptions?.debounceMs ?? 300);

    return () => {
      isActive = false;
      window.clearTimeout(timeout);
    };
  }, [config, enableSearch, maxResults, minQueryLength, query, searchOptions?.debounceMs]);

  useEffect(() => {
    if (!showResults) {
      return undefined;
    }

    function handlePointerDown(event: PointerEvent) {
      const container = searchContainerRef.current;

      if (container && container.contains(event.target as Node)) {
        return;
      }

      setShowResults(false);
    }

    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === 'Escape') {
        setShowResults(false);
      }
    }

    document.addEventListener('pointerdown', handlePointerDown);
    document.addEventListener('keydown', handleKeyDown);

    return () => {
      document.removeEventListener('pointerdown', handlePointerDown);
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [showResults]);

  async function selectLocation(location: FormedibleLocationValue) {
    let nextLocation = location;
    if (!nextLocation.address && config?.reverseGeocodeCallback) {
      try {
        nextLocation = await config.reverseGeocodeCallback(nextLocation.lat, nextLocation.lng);
      } catch {
        nextLocation = { ...nextLocation, address: `${nextLocation.lat}, ${nextLocation.lng}` };
      }
    }

    field.onChange(nextLocation);
    setShowResults(false);
    setError(undefined);
    field.onBlur();
  }

  function updateDraft(nextDraft: FormedibleLocationDraftValue) {
    field.onChange({ ...draft, ...nextDraft });
  }

  function useCurrentLocation() {
    if (!enableGeolocation || typeof navigator === 'undefined' || !navigator.geolocation) {
      setError('Geolocation is not supported by your browser');
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        selectLocation({ lat: position.coords.latitude, lng: position.coords.longitude, address: 'Current Location' });
      },
      () => setError('Failed to get location'),
    );
  }

  function submitManualLocation() {
    const lat = Number.parseFloat(manualLat);
    const lng = Number.parseFloat(manualLng);

    if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
      setError('Invalid coordinates. Please enter valid numbers.');
      return;
    }

    selectLocation({ lat, lng, address: `${lat}, ${lng}` });
  }

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <div className="space-y-3">
        {enableSearch && (
          <div className="relative" ref={searchContainerRef}>
            <Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              id={field.id}
              name={field.name}
              value={query}
              placeholder={fieldConfig.placeholder ?? config?.searchPlaceholder ?? 'Search for an address or place...'}
              disabled={fieldConfig.disabled}
              className={cn('pl-9 pr-9', fieldConfig.inputClassName)}
              onBlur={field.onBlur}
              onFocus={() => setShowResults(results.length > 0)}
              onChange={(event) => updateDraft({ query: event.target.value })}
            />
            {query && (
              <Button type="button" variant="ghost" size="icon" className="absolute right-1 top-1/2 size-7 -translate-y-1/2 text-muted-foreground" onClick={() => updateDraft({ query: '' })}>
                <X className="size-4" />
              </Button>
            )}
            {showResults && results.length > 0 && (
              <div data-slot="location-results" className="absolute z-50 mt-1 max-h-60 w-full overflow-y-auto rounded-md border bg-popover p-1 shadow-md">
                {results.map((result) => (
                  <Button key={`${result.lat}-${result.lng}-${result.address ?? ''}`} type="button" variant="ghost" className="h-auto w-full justify-start rounded-sm px-3 py-2 text-left text-sm" onMouseDown={() => selectLocation(result)}>
                    <span className="font-medium">{result.address ?? `${result.lat}, ${result.lng}`}</span>
                    <span className="block text-xs text-muted-foreground">{result.lat}, {result.lng}</span>
                  </Button>
                ))}
              </div>
            )}
          </div>
        )}
        <div className="flex flex-wrap gap-2">
          {enableGeolocation && (
            <Button variant="outline" disabled={fieldConfig.disabled} onClick={useCurrentLocation}>
              <Navigation className="size-4" />
              Current location
            </Button>
          )}
          {value && (
            <Button variant="ghost" disabled={fieldConfig.disabled} onClick={() => field.onChange(null)}>
              Clear location
            </Button>
          )}
        </div>
        {enableManualEntry && (
          <div className="grid gap-2 sm:grid-cols-[1fr_1fr_auto]">
            <Input value={manualLat} placeholder="Latitude" disabled={fieldConfig.disabled} onChange={(event) => updateDraft({ manualLat: event.target.value })} />
            <Input value={manualLng} placeholder="Longitude" disabled={fieldConfig.disabled} onChange={(event) => updateDraft({ manualLng: event.target.value })} />
            <Button variant="outline" disabled={fieldConfig.disabled} onClick={submitManualLocation}>Use coordinates</Button>
          </div>
        )}
        {value && (
          <div className="flex items-start gap-2 rounded-md border bg-muted/40 p-3 text-sm">
            <MapPin className="mt-0.5 size-4 text-primary" />
            <div>
              <div>{value.address ?? 'Selected location'}</div>
              <div className="text-xs text-muted-foreground">{value.lat}, {value.lng}</div>
            </div>
          </div>
        )}
        {error && <div className="text-sm text-destructive">{error}</div>}
      </div>
    </FieldWrapper>
  );
}

interface FormedibleLocationDraftValue {
  readonly query?: string;
  readonly manualLat?: string;
  readonly manualLng?: string;
}

function isLocationValue(value: unknown): value is FormedibleLocationValue {
  return typeof value === 'object' && value !== null && 'lat' in value && 'lng' in value;
}

function isLocationDraftValue(value: unknown): value is FormedibleLocationDraftValue {
  return typeof value === 'object' && value !== null && !isLocationValue(value);
}

import { PaperclipIcon, UploadCloudIcon, XIcon } from 'lucide-react';
import { useRef, useState } from 'react';

import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import type { FormedibleFieldRenderProps, FormedibleFileRejection, FormedibleFormValues } from '@/lib/formedible/types';
import { cn } from '@/lib/utils';

const rejectionReasonLabels = {
  maxSize: 'exceeds the maximum file size',
  maxFiles: 'exceeds the maximum number of files',
} as const;

export function FileUploadField<TFormValues extends FormedibleFormValues>({ fieldConfig, field }: FormedibleFieldRenderProps<TFormValues>) {
  const config = fieldConfig.fileConfig;
  const accept = fieldConfig.accept ?? config?.accept;
  const multiple = fieldConfig.multiple ?? config?.multiple ?? false;
  const inputRef = useRef<HTMLInputElement>(null);
  const [rejections, setRejections] = useState<readonly FormedibleFileRejection[]>([]);
  const files = getFiles(field.value);

  function setFiles(nextFiles: readonly File[]) {
    const maxFiles = config?.maxFiles;
    const maxSize = config?.maxSize;
    const acceptedFiles: File[] = [];
    const nextRejections: FormedibleFileRejection[] = [];

    nextFiles.forEach((file, index) => {
      if (maxFiles !== undefined && index >= maxFiles) {
        nextRejections.push({ file, reason: 'maxFiles' });
        return;
      }

      if (maxSize !== undefined && file.size > maxSize) {
        nextRejections.push({ file, reason: 'maxSize' });
        return;
      }

      acceptedFiles.push(file);
    });

    setRejections(nextRejections);
    if (nextRejections.length > 0) {
      config?.onFilesRejected?.(nextRejections);
    }

    field.onChange(multiple ? acceptedFiles : acceptedFiles[0] ?? null);
    config?.onFilesChange?.(acceptedFiles);
    field.onBlur();
  }

  function removeFile(file: File) {
    const nextFiles = files.filter((entry) => entry !== file);
    field.onChange(multiple ? nextFiles : null);
    config?.onFileRemove?.(file);
    if (inputRef.current) {
      inputRef.current.value = '';
    }
    field.onBlur();
  }

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <div className="space-y-2">
        <Input
          ref={inputRef}
          id={field.id}
          name={field.name}
          type="file"
          accept={accept}
          multiple={multiple}
          disabled={fieldConfig.disabled}
          className="hidden"
          onChange={(event) => setFiles(Array.from(event.target.files ?? []))}
        />
        {files.length > 0 ? (
          <div className="space-y-2">
            {files.map((file, index) => (
              <div key={index} className="flex items-center justify-between rounded-lg border bg-muted/40 p-2.5">
                <div className="flex min-w-0 items-center gap-2 text-sm">
                  <PaperclipIcon className="size-5 shrink-0 text-primary" />
                  <span className="truncate" title={file.name}>{file.name}</span>
                  <span className="text-xs text-muted-foreground">({(file.size / 1024).toFixed(1)} KB)</span>
                </div>
                <Button variant="ghost" size="icon" className="size-7 text-destructive" disabled={fieldConfig.disabled} aria-label="Remove file" onClick={() => removeFile(file)}>
                  <XIcon className="size-4" />
                </Button>
              </div>
            ))}
          </div>
        ) : (
          <Button
            type="button"
            variant="outline"
            disabled={fieldConfig.disabled}
            className={cn('flex w-full flex-col items-center justify-center rounded-lg border-2 border-dashed border-muted-foreground/50 bg-background p-4 transition-colors hover:border-primary hover:bg-muted/50 disabled:cursor-not-allowed disabled:opacity-50', fieldConfig.inputClassName)}
            onClick={() => inputRef.current?.click()}
          >
            <UploadCloudIcon className="mb-2 size-8 text-muted-foreground" />
            <span className="text-sm font-medium text-muted-foreground">Click or drag and drop a file</span>
            {accept && <span className="mt-1 text-xs text-muted-foreground/80">Accepted types: {accept}</span>}
          </Button>
        )}
        {rejections.length > 0 && (
          <div role="alert" data-slot="file-rejections" className="space-y-1 text-sm text-destructive">
            {rejections.map((rejection, index) => (
              <div key={index}>
                {rejection.file.name} was not uploaded ({rejectionReasonLabels[rejection.reason]}).
              </div>
            ))}
          </div>
        )}
      </div>
    </FieldWrapper>
  );
}

function getFiles(value: unknown): readonly File[] {
  if (typeof File === 'undefined') {
    return [];
  }

  if (value instanceof File) {
    return [value];
  }

  return Array.isArray(value) ? value.filter((entry): entry is File => entry instanceof File) : [];
}

import { ArrowDown, ArrowUp, Plus, Trash2 } from 'lucide-react';

import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { Button } from '@/components/ui/button';
import { arrayItemFieldPath, joinFieldPath } from '@/lib/formedible/field-path';
import { normalizeFieldConfig } from '@/lib/formedible/normalize-field-config';
import { cn } from '@/lib/utils';
import type { FormedibleFieldConfig, FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';

function arrayValue(value: unknown): readonly unknown[] {
  return Array.isArray(value) ? value : [];
}

function objectValue(value: unknown): FormedibleFormValues {
  return typeof value === 'object' && value !== null && !Array.isArray(value) ? (value as FormedibleFormValues) : {};
}

function defaultItemValue<TFormValues extends FormedibleFormValues>(fieldConfig: FormedibleFieldRenderProps<TFormValues>['fieldConfig']) {
  if (fieldConfig.arrayConfig && 'defaultValue' in fieldConfig.arrayConfig) {
    return fieldConfig.arrayConfig.defaultValue;
  }

  if (fieldConfig.arrayConfig?.itemType === 'object') {
    return {};
  }

  if (fieldConfig.arrayConfig?.itemType === 'number') {
    return 0;
  }

  if (fieldConfig.arrayConfig?.itemType === 'checkbox' || fieldConfig.arrayConfig?.itemType === 'switch') {
    return false;
  }

  return '';
}

function primitiveItemField<TFormValues extends FormedibleFormValues>(fieldConfig: FormedibleFieldRenderProps<TFormValues>['fieldConfig']): FormedibleFieldConfig<TFormValues> {
  const itemType = fieldConfig.arrayConfig?.itemType;

  return {
    name: fieldConfig.name,
    type: itemType === 'string' ? 'text' : itemType === 'email' ? 'email' : itemType,
    label: undefined,
    placeholder: typeof fieldConfig.arrayConfig?.itemPlaceholder === 'string' ? fieldConfig.arrayConfig.itemPlaceholder : fieldConfig.placeholder,
  };
}

export function reorderArrayItems(items: readonly unknown[], fromIndex: number, toIndex: number): readonly unknown[] {
  if (fromIndex < 0 || fromIndex >= items.length || toIndex < 0 || toIndex >= items.length) {
    return items;
  }

  const nextItems = [...items];
  const currentItem = nextItems[fromIndex];
  nextItems[fromIndex] = nextItems[toIndex];
  nextItems[toIndex] = currentItem;

  return nextItems;
}

export function ArrayField<TFormValues extends FormedibleFormValues>({ fieldConfig, field, renderField }: FormedibleFieldRenderProps<TFormValues>) {
  const items = arrayValue(field.value);
  const minItems = fieldConfig.arrayConfig?.minItems ?? 0;
  const maxItems = fieldConfig.arrayConfig?.maxItems;
  const sortable = fieldConfig.arrayConfig?.sortable ?? false;
  const itemLabel = typeof fieldConfig.arrayConfig?.itemLabel === 'string' ? fieldConfig.arrayConfig.itemLabel : 'Item';
  const addButtonLabel = typeof fieldConfig.arrayConfig?.addButtonLabel === 'string' ? fieldConfig.arrayConfig.addButtonLabel : `Add ${itemLabel}`;
  const removeButtonLabel = typeof fieldConfig.arrayConfig?.removeButtonLabel === 'string' ? fieldConfig.arrayConfig.removeButtonLabel : 'Remove';
  const canAdd = maxItems === undefined || items.length < maxItems;

  if (!renderField) {
    return <FieldWrapper fieldConfig={fieldConfig} field={field}>{undefined}</FieldWrapper>;
  }

  function updateItems(nextItems: readonly unknown[]) {
    field.onChange([...nextItems]);
  }

  function addItem() {
    if (canAdd) {
      updateItems([...items, defaultItemValue(fieldConfig)]);
    }
  }

  function removeItem(index: number) {
    if (items.length > minItems) {
      updateItems(items.filter((_item, itemIndex) => itemIndex !== index));
    }
  }

  function moveItem(index: number, direction: -1 | 1) {
    const targetIndex = index + direction;

    if (targetIndex < 0 || targetIndex >= items.length) {
      return;
    }

    updateItems(reorderArrayItems(items, index, targetIndex));
  }

  return (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <div data-formedible-array-field={field.name} className="space-y-3">
        {items.map((item, index) => {
          const itemPath = arrayItemFieldPath(field.name, index);
          const isObjectItem = fieldConfig.arrayConfig?.itemType === 'object';
          const objectFields = fieldConfig.arrayConfig?.objectConfig?.fields ?? [];
          const objectLayout = fieldConfig.arrayConfig?.objectConfig?.layout ?? 'stack';
          const objectColumns = fieldConfig.arrayConfig?.objectConfig?.columns ?? 1;

          return (
            <div key={itemPath} data-formedible-array-item={itemPath} className="space-y-3 rounded-md border border-border p-3">
              <div className="flex items-center justify-between gap-2">
                <div className="text-sm font-medium">{`${itemLabel} ${index + 1}`}</div>
                <div className="flex gap-1">
                  {sortable ? (
                    <>
                      <Button variant="ghost" size="icon" aria-label={`Move ${itemLabel} ${index + 1} up`} disabled={index === 0} onClick={() => moveItem(index, -1)}>
                        <ArrowUp aria-hidden="true" className="size-4" />
                      </Button>
                      <Button variant="ghost" size="icon" aria-label={`Move ${itemLabel} ${index + 1} down`} disabled={index === items.length - 1} onClick={() => moveItem(index, 1)}>
                        <ArrowDown aria-hidden="true" className="size-4" />
                      </Button>
                    </>
                  ) : undefined}
                  <Button variant="ghost" size="icon" aria-label={`${removeButtonLabel} ${index + 1}`} disabled={items.length <= minItems} onClick={() => removeItem(index)}>
                    <Trash2 aria-hidden="true" className="size-4" />
                  </Button>
                </div>
              </div>
              {isObjectItem ? (
                <div
                  className={cn('space-y-4', objectLayout === 'grid' && objectColumns > 1 ? 'grid gap-4 space-y-0' : undefined)}
                  style={objectLayout === 'grid' && objectColumns > 1 ? { gridTemplateColumns: `repeat(${objectColumns}, minmax(0, 1fr))` } : undefined}
                >
                  {objectFields.map((nestedField) => {
                    const nestedConfig = normalizeFieldConfig<TFormValues>(nestedField);
                    const nestedName = joinFieldPath(itemPath, nestedConfig.name);

                    return renderField(nestedConfig, {
                      key: nestedName,
                      name: nestedName,
                      localValues: objectValue(item),
                    });
                  })}
                </div>
              ) : (
                renderField(normalizeFieldConfig<TFormValues>(primitiveItemField(fieldConfig)), {
                  key: itemPath,
                  name: itemPath,
                  localValues: { value: item },
                })
              )}
            </div>
          );
        })}
        <Button variant="outline" size="sm" disabled={!canAdd} onClick={addItem}>
          <Plus aria-hidden="true" className="size-4" />
          {addButtonLabel}
        </Button>
      </div>
    </FieldWrapper>
  );
}

import { useState } from 'react';

import { FieldWrapper } from '@/components/formedible/fields/field-wrapper';
import { Button } from '@/components/ui/button';
import { joinFieldPath } from '@/lib/formedible/field-path';
import { normalizeFieldConfig } from '@/lib/formedible/normalize-field-config';
import { cn } from '@/lib/utils';
import type { FormedibleFieldRenderProps, FormedibleFormValues } from '@/lib/formedible/types';

function objectValue(value: unknown): FormedibleFormValues {
  return typeof value === 'object' && value !== null && !Array.isArray(value) ? (value as FormedibleFormValues) : {};
}

export function ObjectField<TFormValues extends FormedibleFormValues>({ fieldConfig, field, renderField }: FormedibleFieldRenderProps<TFormValues>) {
  const config = fieldConfig.objectConfig;
  const fields = config?.fields ?? fieldConfig.nestedFields ?? [];
  const columns = config?.columns ?? 1;
  const layout = config?.layout ?? 'stack';
  const collapsible = config?.collapsible ?? false;
  const [isExpanded, setIsExpanded] = useState(config?.defaultExpanded !== false);
  const localValues = objectValue(field.value);

  if (!renderField) {
    return <FieldWrapper fieldConfig={fieldConfig} field={field}>{undefined}</FieldWrapper>;
  }

  const nestedFields = (
    <div
      id={`${field.id}-object-fields`}
      data-formedible-object-field={field.name}
      className={cn('space-y-4', layout === 'grid' && columns > 1 ? 'grid gap-4 space-y-0' : undefined)}
      style={layout === 'grid' && columns > 1 ? { gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))` } : undefined}
    >
      {fields.map((nestedField) => {
        const nestedConfig = normalizeFieldConfig<TFormValues>(nestedField);
        const nestedName = joinFieldPath(field.name, nestedConfig.name);

        return renderField(nestedConfig, {
          key: nestedName,
          name: nestedName,
          localValues,
        });
      })}
    </div>
  );

  const content = (
    <FieldWrapper fieldConfig={fieldConfig} field={field}>
      <div className="space-y-3">
        {collapsible ? (
          <Button
            type="button"
            variant="ghost"
            data-formedible-object-toggle={field.name}
            aria-expanded={isExpanded}
            aria-controls={`${field.id}-object-fields`}
            disabled={fieldConfig.disabled}
            className="text-muted-foreground hover:text-foreground h-auto px-1.5 py-0.5 text-xs"
            onClick={() => setIsExpanded((previous) => !previous)}
          >
            {isExpanded ? config?.collapseLabel ?? 'Collapse' : config?.expandLabel ?? 'Expand'}
          </Button>
        ) : undefined}
        {!collapsible || isExpanded ? nestedFields : undefined}
      </div>
    </FieldWrapper>
  );

  if (config?.showCard) {
    return (
      <div data-formedible-object-card={field.name} className="rounded-lg border bg-card p-4 shadow-xs">
        {content}
      </div>
    );
  }

  return content;
}

import type { ReactNode } from 'react';

import type { FormedibleFieldOption, FormedibleFormValues, FormedibleOptionConfig, NormalizedFieldConfig } from '@/lib/formedible/types';

export function normalizeOption(option: FormedibleFieldOption): FormedibleOptionConfig {
  return typeof option === 'string' ? { value: option, label: option } : option;
}

export function labelToText(label: ReactNode): string {
  return typeof label === 'string' || typeof label === 'number' ? String(label) : '';
}

export function resolveFieldOptions<TFormValues extends FormedibleFormValues>(
  fieldConfig: NormalizedFieldConfig<TFormValues>,
  formValues: FormedibleFormValues | undefined,
): readonly FormedibleOptionConfig[] {
  const options = typeof fieldConfig.options === 'function' ? fieldConfig.options((formValues ?? {}) as TFormValues) : fieldConfig.options;

  return Array.isArray(options) ? options.map(normalizeOption) : [];
}

export function getStringArray(value: unknown): readonly string[] {
  return Array.isArray(value) ? value.filter((entry): entry is string => typeof entry === 'string') : [];
}

export function getNumber(value: unknown, fallback: number): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : fallback;
}

export function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

